interface PartitionPage extends Omit<ProfileCategory, 'group' | 'path' | 'eyebrow' | 'heroImage' | 'imageBase' | 'process' | 'compareColumns' | 'faq'> {
  eyebrow: string;
  faq: [string, string][];
}

const page = (p: PartitionPage): ProfileCategory => {
  if (p.faq.length !== 8) throw new Error(`partition RU page ${p.slug}: expected 8 own FAQs`);
  return {
    ...p,
    group: 'partitions',
    path: P(p.slug),
    eyebrow: `Стеклянные перегородки / ${p.eyebrow}`,
    heroImage: `hero-${p.slug}`,
    imageBase: PARTITION_IMG,
    process: PROCESS,
    compareColumns: ['Система', 'Тип', 'Стекло', 'Особенность', 'Для чего'],
    faq: [...p.faq, ...COMMON],
    catalogButton: 'Смотреть системы',
    optionsLabel: 'Система',
    catalogNote: 'Технические параметры приведены для типовых конфигураций. Стоимость, толщину стекла, фурнитуру и двери определяем после замера — пришлите план или фото с размерами для расчёта.'
  };
};

